window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[273]={"id":"273","numero":273,"titre":"Dysphagie","objectifs":[{"id":"273-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la dysphagie","contenu":"<div class=\"notion-course\"><p>La <span><span class=\"nc-blue_bg\">dysphagie</span></span> est définie comme une <span><span class=\"nc-blue_bg\">sensation de</span> <span class=\"nc-blue_bg nc-bold\">gêne</span> <span class=\"nc-blue_bg\">ou d'</span><span class=\"nc-blue_bg nc-bold\">obstacle</span> <span class=\"nc-blue_bg\">à la progression du bol alimentaire</span></span>, survenant <strong><span class=\"nc-red nc-bold\">au cours de la déglutition</span></strong>. C'est cette notion de blocage du transit alimentaire qui la définit.</p>\n      <p>Rappel — la <span>déglutition</span> est le mécanisme qui comprend la <span>préhension des aliments</span>, leur <span>préparation dans la bouche</span>, leur <span>propulsion de la bouche vers l'estomac</span>, ainsi que la <span><span class=\"nc-green nc-bold\">protection des voies respiratoires</span></span>.</p>\n      <p><strong>Diagnostics différentiels</strong> — plusieurs symptômes sont à distinguer de la vraie <span>dysphagie</span>, car aucun ne comporte de blocage alimentaire :</p>\n      <table>\n        <thead><tr><th>Entité</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span>Odynophagie</span></td><td><span>Douleur</span> ressentie lors de la progression des aliments dans l'œsophage, <span><span class=\"nc-red nc-bold\">sans sensation de blocage</span></span></td></tr>\n          <tr><td>Globus pharyngé</td><td><span class=\"nc-blue_bg\">Sensation de</span> boule ou de compression cervicale, généralement hors déglutition ; mécanismes multiples. Le stress peut intervenir, sans autoriser un diagnostic psychologique automatique.</td></tr>\n          <tr><td><span>Anorexie</span></td><td><span>Perte d'appétit</span> entraînant une baisse des prises alimentaires</td></tr>\n          <tr><td><span>Satiété précoce</span></td><td>Le bol alimentaire descend normalement mais la <span>faim est rapidement coupée</span></td></tr>\n          <tr><td><span>Syndrome de rumination</span></td><td><span class=\"nc-blue_bg\">Régurgitations</span> répétées sans effort de vomissement ; phénomène souvent involontaire, à distinguer du blocage alimentaire.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège ⚠️</strong> — l'<span><span class=\"nc-blue nc-bold\">odynophagie</span></span> (déglutition douloureuse) n'est <strong>pas</strong> une <span><span class=\"nc-yellow_bg\">dysphagie</span></span> : c'est une <span class=\"nc-blue_bg\">douleur</span> sans <span class=\"nc-blue_bg nc-bold\">obstacle</span>. <span>Les</span> deux peuvent toutefois coexister (« <span class=\"nc-yellow_bg\">dysphagie</span> douloureuse »), orientant alors vers une <span class=\"nc-orange nc-bold\">infection</span>, une œsophagite ou une <span class=\"nc-orange nc-bold\">tumeur</span>.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.snfge.org/tncd/cancer-loesophage-jonction-oeso-gastrique\" target=\"_blank\" rel=\"noopener noreferrer\">TNCD · œsophage et jonction œsogastrique</a></li><li><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC12269739/\" target=\"_blank\" rel=\"noopener noreferrer\">UEG–ESNM · dysphagies, recommandations 2025</a></li></ul></details>","frequence":1},{"id":"273-2","rang":"A","rubrique":"Définition","titre":"Connaître les deux types de dysphagie","contenu":"<div class=\"notion-course\"><p>La <span><span class=\"nc-blue_bg\">dysphagie</span></span> se classe selon <strong>deux axes complémentaires</strong> : le <span>siège</span> de la gêne et le <span>mécanisme</span> en cause. Ces deux axes orientent l'ensemble de la démarche diagnostique.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Axe 1 — selon la localisation</h4>\n      <table>\n        <thead><tr><th>Type</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span>Dysphagie œsophagienne</span></td><td><span class=\"nc-blue_bg\">Sensation de</span> <span>blocage du bol alimentaire <span class=\"nc-red nc-bold\">au niveau rétrosternal</span></span>, après le déclenchement de la déglutition</td></tr>\n          <tr><td><span><span class=\"nc-orange_bg\">Dysphagie oropharyngée</span></span></td><td><span>Difficulté à initier la déglutition</span> et à propulser le bol dans l'œsophage, gêne ressentie <span><span class=\"nc-red nc-bold\">au niveau cervical</span></span> ; causes essentiellement <span><span class=\"nc-orange nc-bold\">ORL</span></span> ou <span>neurologiques</span></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Axe 2 — selon le mécanisme</h4>\n      <table>\n        <thead><tr><th>Type</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-brown_bg\">Dysphagie lésionnelle</span></span></td><td>Liée à une <span>lésion organique œsophagienne</span> ou à une <span><span class=\"nc-red_bg\">compression extrinsèque</span></span></td></tr>\n          <tr><td><span><span class=\"nc-brown_bg\">Dysphagie fonctionnelle</span></span> (non lésionnelle)</td><td><span>Aucune lésion identifiée</span> : anomalie de la <span>dynamique propulsive</span> du bol alimentaire</td></tr>\n        </tbody>\n      </table></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.snfge.org/tncd/cancer-loesophage-jonction-oeso-gastrique\" target=\"_blank\" rel=\"noopener noreferrer\">TNCD · œsophage et jonction œsogastrique</a></li><li><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC12269739/\" target=\"_blank\" rel=\"noopener noreferrer\">UEG–ESNM · dysphagies, recommandations 2025</a></li></ul></details>","frequence":0},{"id":"273-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments à l’interrogatoire orientant vers une dysphagie lésionnelle ou non lésionnelle","contenu":"<div class=\"notion-course\"><p>Devant toute <span><span class=\"nc-blue_bg\">dysphagie</span></span>, l'interrogatoire est l'étape clé : il oriente d'emblée vers une <span class=\"nc-brown_bg\">dysphagie </span><span><span class=\"nc-brown_bg\">lésionnelle</span></span> ou <span>non lésionnelle</span>, précise le siège <span>oropharyngé</span> ou <span>œsophagien</span>, et recherche <span>les</span> <span>signes de gravité</span>. <strong>Objectif à haut rendement — 3 QCM EDN.</strong></p>\n      <table>\n        <thead><tr><th>Élément</th><th>Orientation diagnostique</th></tr></thead>\n        <tbody>\n          <tr><td><span>Terrain</span></td><td><span>Intoxication alcoolo-tabagique</span> ; antécédents personnels ; traitements en cours (<span><span class=\"nc-pink nc-bold\">AINS</span></span>, <span>biphosphonates</span>, <span><span class=\"nc-pink nc-bold\">tétracyclines</span></span>, <span>chlorure de potassium</span>)</td></tr>\n          <tr><td><span>Évolution</span></td><td><strong>Aggravation croissante :</strong> évocatrice d'une pathologie <span>tumorale</span><br><strong>Survenue brutale :</strong> <span><span class=\"nc-red nc-bold\">corps</span> étranger</span><br><strong>Installation progressive :</strong> <span><span class=\"nc-red nc-bold\">sténose œsophagienne</span></span></td></tr>\n          <tr><td>Type d'aliment</td><td><strong>Prédominance sur <span>les</span> <span class=\"nc-red nc-bold\">solides</span> :</strong> <span><span class=\"nc-yellow_bg\">dysphagie</span></span> <span>lésionnelle</span><br><strong>Prédominance sur les <span class=\"nc-red nc-bold\">liquides</span> :</strong> <span class=\"nc-yellow_bg\">dysphagie</span> <span>non lésionnelle</span><br><strong>Dysphagie <span class=\"nc-red nc-bold\">paradoxale</span></strong> (prédominant sur les <span class=\"nc-red nc-bold\">liquides</span>) : classique de l'<span><span class=\"nc-red nc-bold\">achalasie</span></span>, mais inconstante<br><strong>Prédominance sur les <span class=\"nc-red nc-bold\">solides</span> :</strong> aussi possible dans un défaut de propulsion pharyngée ou d'ouverture du SSO (valeur relative)</td></tr>\n          <tr><td><span class=\"nc-yellow_bg\">Stase salivaire</span></td><td><span>Très bon signe d'organicité</span> : bon indicateur d'une <span><span class=\"nc-red nc-bold\">baisse de la propulsion pharyngée</span></span> ou d'un <span><span class=\"nc-red nc-bold\">trouble de la relaxation du SSO</span></span></td></tr>\n          <tr><td>Symptômes associés</td><td><strong><span class=\"nc-brown_bg\">Dysphonie</span>, <span><span class=\"nc-brown_bg\">dyspnée</span></span> :</strong> <span><span class=\"nc-orange nc-bold\">paralysie laryngée</span></span> associée, obstacle laryngo-trachéal<br><strong><span>Dysphagie</span> douloureuse (odynophagie) :</strong> <span><span class=\"nc-orange nc-bold\">infection</span></span>, <span>œsophagite</span>, <span>tumeur</span><br><strong>Ruminations, <span><span class=\"nc-blue_bg\">régurgitations</span></span>, <span class=\"nc-blue_bg\">bruits hydro-aériques</span> :</strong> <span>diverticule de Zenker</span><br><strong><span>Otalgie</span> réflexe :</strong> doit faire <span>rechercher un cancer</span> du <span class=\"nc-red nc-bold\">pharynx</span> ou du vestibule laryngé</td></tr>\n          <tr><td>Atteinte oropharyngée</td><td><strong>Temps volontaire :</strong> troubles des <span>praxies buccales</span>, <span>bavage</span>, <span>incontinence labiale</span>, résidus alimentaires buccaux<br><strong>Temps pharyngo-laryngé :</strong> <span>voix gargouillante / humide</span> (<span class=\"nc-yellow_bg\">stase salivaire</span> dans l'hypopharynx), déglutition répétée d'une même bouchée<br><strong>Défaut de <span class=\"nc-green nc-bold\">protection des voies respiratoires</span> :</strong> <span><span class=\"nc-yellow_bg\">régurgitations nasales</span></span>, <span><span class=\"nc-yellow_bg\">toux au moment des repas</span></span>, <span><span class=\"nc-yellow_bg\">fausses routes</span></span><span class=\"nc-yellow_bg\"> alimentaires ou salivaires</span><br>→ oriente vers une <span><span class=\"nc-orange_bg\">dysphagie</span></span><span class=\"nc-orange_bg\"> </span><span><span class=\"nc-orange_bg\">oropharyngée</span></span></td></tr>\n          <tr><td><span>Signes de gravité</span></td><td><span><span class=\"nc-purple_bg\">Infections pulmonaires</span> / pneumopathies à répétition</span> sur <span class=\"nc-blue_bg\">fausses routes</span> ; <span>perte de poids</span> ; <span><span class=\"nc-red_bg\">dénutrition</span></span> ; <span><span class=\"nc-red_bg\">déshydratation</span></span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Réflexe EDN 🚩</strong> — <span>toute <span class=\"nc-yellow_bg\">dysphagie</span> doit être considérée comme lésionnelle (cancer de l'œsophage) jusqu'à preuve du contraire</span>. L'<span><span class=\"nc-yellow_bg\">endoscopie</span></span> œsogastroduodénale avec <span>biopsies</span> est donc systématique.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.snfge.org/tncd/cancer-loesophage-jonction-oeso-gastrique\" target=\"_blank\" rel=\"noopener noreferrer\">TNCD · œsophage et jonction œsogastrique</a></li><li><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC12269739/\" target=\"_blank\" rel=\"noopener noreferrer\">UEG–ESNM · dysphagies, recommandations 2025</a></li></ul></details>","frequence":3},{"id":"273-4","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’examen complémentaire non biologique à effectuer en première intention devant une dysphagie","contenu":"<div class=\"notion-course\"><p>L'<span><span class=\"nc-yellow_bg\">endoscopie</span> œsogastroduodénale (EOGD)</span> est l'<strong>examen clé de <span>première intention</span> devant TOUTE <span><span class=\"nc-blue_bg\">dysphagie</span></span></strong>. Elle visualise directement la muqueuse œsophagienne, gastrique et duodénale et permet la réalisation de <span>biopsies</span>.</p>\n      <ul>\n        <li><strong><span><span class=\"nc-blue nc-bold\">Biopsies</span></span><span class=\"nc-blue nc-bold\"> systématiques</span></strong>, <span>même si la muqueuse paraît macroscopiquement normale</span> : recherche d'une <span>œsophagite à éosinophiles</span>, <span class=\"nc-green_bg\">cause classique de </span><span><span class=\"nc-green_bg\">dysphagie</span></span><span class=\"nc-green_bg\"> à </span><span><span class=\"nc-green_bg\">endoscopie</span></span><span class=\"nc-green_bg\"> normale</span>.</li>\n        <li>Une <span>sensation de ressaut au passage de l'endoscope</span> à travers la <span>jonction œsogastrique</span> est évocatrice d'un <span><span class=\"nc-orange nc-bold\">trouble moteur</span> œsophagien</span>.</li>\n        <li><strong>Limites :</strong> l'<span><span class=\"nc-yellow_bg\">endoscopie</span></span> peut être <span>incomplète</span> en cas de <span><span class=\"nc-orange nc-bold\">sténose non franchissable</span></span> ou de <span><span class=\"nc-orange nc-bold\">stase alimentaire</span></span> abondante.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir</strong> — l'<span>EOGD</span> est demandée en <span>première intention</span> quel que soit le type de <span>dysphagie</span> ; <span>les</span> <span>biopsies</span> sont indispensables, car une muqueuse macroscopiquement <span class=\"nc-green_bg\">normale</span> n'élimine pas une œsophagite à <span>éosinophiles</span>.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.snfge.org/tncd/cancer-loesophage-jonction-oeso-gastrique\" target=\"_blank\" rel=\"noopener noreferrer\">TNCD · œsophage et jonction œsogastrique</a></li><li><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC12269739/\" target=\"_blank\" rel=\"noopener noreferrer\">UEG–ESNM · dysphagies, recommandations 2025</a></li></ul></details>","frequence":0},{"id":"273-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires non biologiques à effectuer en deuxième intention devant une dysphagie","contenu":"<div class=\"notion-course\"><p><span>Les</span> examens de seconde intention sont indiqués lorsque l'<span>EOGD</span> avec <span>biopsies</span> est <strong>normale</strong> ou techniquement insuffisante. Ils diffèrent selon que la <span>dysphagie</span> est œsophagienne ou oropharyngée.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span>Dysphagie</span> œsophagienne</h4>\n      <table>\n        <thead><tr><th>Examen</th><th>Indication et apport</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-blue_bg\">Manométrie œsophagienne</span></span></td><td>Indiquée en 2ᵉ intention si <span>dysphagie</span> inexpliquée par une <span>EOGD</span> avec <span>biopsies</span> normales ; réalisée en ambulatoire chez un patient vigile. Évalue le <span><span class=\"nc-blue_bg\">péristaltisme œsophagien</span></span> (<span><span class=\"nc-red nc-bold\">absent dans l'achalasie</span></span>) et la <span>relaxation du SIO</span> (<span>défaut de relaxation dans l'<span class=\"nc-red nc-bold\">achalasie</span></span>)</td></tr>\n          <tr><td><span>TDM thoraco-abdomino-pelvienne injectée</span></td><td>Avec opacification digestive haute : recherche une <span><span class=\"nc-red_bg\">compression extrinsèque</span></span> — <span class=\"nc-orange nc-bold\">volumineuse </span><span><span class=\"nc-orange nc-bold\">hernie hiatale par roulement</span></span>, <span><span class=\"nc-orange nc-bold\">diverticule œsophagien</span></span>, <span><span class=\"nc-orange nc-bold\">tumeur</span> médiastinale ou pulmonaire</span>, <span>adénopathies</span></td></tr>\n          <tr><td><span><span class=\"nc-blue_bg\">Écho-endoscopie haute</span></span></td><td>En cas de suspicion de <span>tumeur sous-muqueuse</span> à l'<span>EOGD</span> : caractérise la <span>lésion</span> et permet de la ponctionner</td></tr>\n          <tr><td><span>TOGD</span></td><td>Transit baryté utile en complément dans certaines situations : <span class=\"nc-red nc-bold\">achalasie</span>, <span class=\"nc-orange nc-bold\">diverticule de Zenker</span>, anomalie morphologique ou <span class=\"nc-yellow_bg\">dysphagie</span> restant inexpliquée après bilan adapté.</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span><span class=\"nc-orange_bg\">Dysphagie</span></span><span class=\"nc-orange_bg\"> oropharyngée</span></h4>\n      <table>\n        <thead><tr><th>Examen</th><th>Apport</th></tr></thead>\n        <tbody>\n          <tr><td>Exploration de la prise alimentaire</td><td>Repas test pris devant un <span>observateur</span> médical ou paramédical (<span class=\"nc-brown_bg\">diététicienne</span>, <span class=\"nc-brown_bg\">orthophoniste</span>, IDE, aide-soignant) ; au terme du repas, des <span>adaptations de texture</span> peuvent être décidées</td></tr>\n          <tr><td><span><span class=\"nc-yellow_bg\">Nasofibroscopie</span> de la déglutition</span></td><td>Peu invasive ; observe le carrefour pharyngo-laryngé lors de la déglutition d'aliments de consistance variable ; diagnostic indirect des troubles (<span>toux</span>, <span class=\"nc-yellow_bg\">stase salivaire</span>, résidus hypopharyngés, <span class=\"nc-blue_bg\">fausses routes</span> secondaires)</td></tr>\n          <tr><td><span>Radio-cinéma de déglutition</span> (<span class=\"nc-blue nc-bold\">vidéo-fluoroscopie</span>)</td><td>Vidéofluoroscopie : examen dynamique des temps oral, pharyngé et œsophagien ; permet d’étudier les <span class=\"nc-blue_bg\">fausses routes</span> et les adaptations de posture ou de consistance. Position adaptée au patient et au protocole, généralement assise ; irradiation et coopération à prendre en compte.</td></tr>\n          <tr><td><span>Panendoscopie ORL</span></td><td>Tube rigide sous <span>anesthésie générale</span> ; examine le <span class=\"nc-pink nc-bold\">pharynx</span> et la <span class=\"nc-pink nc-bold\">bouche œsophagienne</span> — indispensable au bilan d'un <span>carcinome des VADS</span></td></tr>\n          <tr><td><span>TDM cervico-thoracique</span></td><td><strong>Systématique en cas de <span class=\"nc-red nc-bold\">paralysie laryngée</span></strong> : recherche une <span>compression du <span class=\"nc-purple_bg\">nerf vague (X)</span></span> ; recherche aussi une <span class=\"nc-red_bg\">compression extrinsèque</span></td></tr>\n          <tr><td><span>IRM du tronc cérébral</span></td><td>IRM du tronc cérébral si suspicion <span class=\"nc-orange nc-bold\">neurologique</span> centrale ; ce n’est pas un examen systématique de toute <span class=\"nc-blue_bg\">dysphagie</span> inexpliquée.</td></tr>\n        </tbody>\n      </table></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.snfge.org/tncd/cancer-loesophage-jonction-oeso-gastrique\" target=\"_blank\" rel=\"noopener noreferrer\">TNCD · œsophage et jonction œsogastrique</a></li><li><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC12269739/\" target=\"_blank\" rel=\"noopener noreferrer\">UEG–ESNM · dysphagies, recommandations 2025</a></li></ul></details>","frequence":0},{"id":"273-6","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales étiologies de dysphagie lésionnelle (tumorale ou non tumorale) et non lésionnelle","contenu":"<div class=\"notion-course\"><p><span>Les</span> étiologies de <span>dysphagie</span> œsophagienne se répartissent en deux grands cadres, opposés par leur sémiologie et leur démarche.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span><span class=\"nc-brown_bg\">Dysphagie</span></span><span class=\"nc-brown_bg\"> lésionnelle</span></h4>\n      <p>Évocateurs : prédominance sur <span>les</span> <span class=\"nc-red nc-bold\">solides</span>, <span class=\"nc-red nc-bold\">aggravation avec le temps</span>, <span class=\"nc-red nc-bold\">retentissement sur l'état général</span>, sténose organique à l'<span><span class=\"nc-yellow_bg\">endoscopie</span></span>.</p>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><span>Tumorale</span></td><td><span>Cancer de l'œsophage</span> (<span>carcinome</span> épidermoïde, adénocarcinome) : <span>lésion</span> <span class=\"nc-red nc-bold\">ulcéro-bourgeonnante</span>, <span class=\"nc-red nc-bold\">irrégulière</span>, <span class=\"nc-red nc-bold\">saignant au </span><span><span class=\"nc-red nc-bold\">contact</span></span>, <span><span class=\"nc-red nc-bold\">sténose excentrée</span></span></td></tr>\n          <tr><td><span class=\"nc-red_bg\">Compression extrinsèque</span></td><td><span>Carcinome bronchopulmonaire</span> ; <span>tumeurs ou adénopathies médiastinales</span></td></tr>\n          <tr><td>Sténoses non tumorales</td><td><span class=\"nc-green_bg nc-bold\">Fibreuses</span>, <span class=\"nc-green_bg nc-bold\">régulières</span>, <span class=\"nc-green_bg nc-bold\">centrées</span> : <span>œsophagite à éosinophiles</span> ; sténose <span><span class=\"nc-orange nc-bold\">peptique</span></span> ; <span><span class=\"nc-orange nc-bold\">caustique</span></span> ; <span><span class=\"nc-orange nc-bold\">post-radique</span></span> ; <span><span class=\"nc-orange nc-bold\">cicatricielle</span></span> ; <span>anastomotique post-œsophagectomie</span> ; <span>anneau de Schatzki</span> ; <span><span class=\"nc-orange nc-bold\">syndrome de Plummer-Vinson</span></span> ; <span><span class=\"nc-orange_bg\">tumeurs sous-muqueuses bénignes</span></span></td></tr>\n          <tr><td>Œsophagites sans sténose</td><td>Symptôme prédominant = <span><span class=\"nc-blue nc-bold\">odynophagie</span></span> : <span><span class=\"nc-pink nc-bold\">AINS</span></span> ; <span>biphosphonates</span> ; <span><span class=\"nc-pink nc-bold\">tétracyclines</span></span> ; <span>chlorure de potassium</span> ; <span><span class=\"nc-purple nc-bold\">Candida</span></span>, <span><span class=\"nc-purple nc-bold\">CMV</span></span>, <span><span class=\"nc-purple nc-bold\">HSV</span></span> chez l'immunodéprimé</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span>Dysphagie</span> non lésionnelle</h4>\n      <p>Évocateurs : <span><span class=\"nc-yellow_bg\">dysphagie</span></span> fluctuant dans le temps, <span class=\"nc-brown_bg\">retentissement inconstant sur l'état général</span>, <span><span class=\"nc-yellow_bg\">endoscopie</span></span> <span class=\"nc-green nc-bold\">souvent normale</span> ; quantification par le <span>score d'Eckardt</span>.</p>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td>Troubles moteurs primaires</td><td><span><span class=\"nc-red nc-bold\">Achalasie</span></span> (absence de péristaltisme + défaut de relaxation du SIO) ; <span>spasmes œsophagiens</span> ; <span>œsophage hypercontractile « <span class=\"nc-red nc-bold\">marteau-piqueur</span> »</span> ; <span>péristaltisme inefficace ou absent</span></td></tr>\n          <tr><td>Troubles moteurs secondaires</td><td><span><span class=\"nc-orange_bg\">Sclérodermie</span></span> ; <span><span class=\"nc-orange_bg\">dermatomyosite</span></span> ; <span><span class=\"nc-orange_bg\">lupus</span></span> ; <span>syndrome de Gougerot-Sjögren</span> ; <span class=\"nc-orange_bg\">myopathie</span></td></tr>\n          <tr><td><span><span class=\"nc-brown_bg\">Dysphagie</span></span><span class=\"nc-brown_bg\"> fonctionnelle</span></td><td>Diagnostic d'élimination, après bilan négatif</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Repère sémiologique</strong> — une <span><span class=\"nc-yellow_bg\">dysphagie</span></span> aux <span><span class=\"nc-red nc-bold\">solides</span></span>, d'<span>aggravation progressive</span>, avec <span><span class=\"nc-red nc-bold\">retentissement sur l'état général</span></span> = lésionnelle jusqu'à preuve du contraire. Une <span class=\"nc-yellow_bg\">dysphagie</span> <span><span class=\"nc-red nc-bold\">capricieuse</span></span>, <span><span class=\"nc-red nc-bold\">paradoxale</span></span> (sur <span>les</span> <span class=\"nc-red nc-bold\">liquides</span>) et fluctuante oriente vers un <span class=\"nc-orange nc-bold\">trouble moteur</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 305 — Tumeur de l'œsophage · 271 — <span>RGO</span> - hernie hiatale</em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Une <span class=\"nc-orange_bg\">dysphagie oropharyngée</span> oriente d’abord vers l’évaluation de la déglutition et des voies aériennes ; une <span class=\"nc-yellow_bg\">dysphagie</span> œsophagienne vers l’<span class=\"nc-yellow_bg\">endoscopie</span> avec biopsies, puis manométrie si indiquée. Un <span class=\"nc-orange nc-bold\">trouble moteur</span> peut constituer une maladie organique sans <span class=\"nc-blue_bg nc-bold\">obstacle</span> visible.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.snfge.org/tncd/cancer-loesophage-jonction-oeso-gastrique\" target=\"_blank\" rel=\"noopener noreferrer\">TNCD · œsophage et jonction œsogastrique</a></li><li><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC12269739/\" target=\"_blank\" rel=\"noopener noreferrer\">UEG–ESNM · dysphagies, recommandations 2025</a></li></ul></details>","frequence":0},{"id":"273-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principales étiologies d’une dysphagie d’origine pharyngolaryngée et en apprécier la gravité","contenu":"<div class=\"notion-course\"><p>La <span><span class=\"nc-blue_bg\">dysphagie</span></span> d'origine pharyngo-laryngée (oropharyngée) relève de causes <span class=\"nc-orange nc-bold\">ORL</span> et neurologiques. L'appréciation de sa gravité est essentielle : elle expose à des complications respiratoires et nutritionnelles.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Étiologies</h4>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td>Causes tumorales</td><td><span>Cancer du <span class=\"nc-red nc-bold\">pharynx</span></span>, du <span><span class=\"nc-red nc-bold\">larynx</span></span>, du <span><span class=\"nc-red nc-bold\">1/3 supérieur de l'œsophage</span></span> ; <span>cancer de la cavité buccale</span> (<span><span class=\"nc-blue_bg\">dysphagie</span></span> alors tardive)</td></tr>\n          <tr><td>Causes extrinsèques</td><td><span><span class=\"nc-blue_bg\">Volumineux goitre thyroïdien plongeant</span></span> ; <span><span class=\"nc-blue_bg\">anévrisme de l'aorte thoracique</span></span> ; <span><span class=\"nc-red nc-bold\">tumeurs du médiastin</span></span> ; <span><span class=\"nc-blue_bg\">anomalie vertébrale</span></span> — la <span>TDM</span> thoracique injectée précise l'extension</td></tr>\n          <tr><td>Atteinte du SSO</td><td><span><span class=\"nc-orange_bg\">Diverticule de Zenker</span></span> ; <span>achalasie du sphincter supérieur</span> (hypertonie du crico-pharyngien) ; <span><span class=\"nc-orange nc-bold\">syndrome de Plummer-Vinson</span></span> ; <span>séquelles d'ingestion de <span class=\"nc-orange nc-bold\">caustique</span></span></td></tr>\n          <tr><td>Causes neurologiques</td><td>Maladies neurodégénératives (<span><span class=\"nc-red_bg\">Parkinson</span></span>, <span><span class=\"nc-red_bg\">Alzheimer</span></span>, <span class=\"nc-red_bg\">démence sénile</span>) ; <span><span class=\"nc-orange_bg\">myasthénie</span></span> ; <span><span class=\"nc-orange_bg\">AVC</span></span> ; <span><span class=\"nc-orange_bg\">SLA</span></span> ; <span><span class=\"nc-orange_bg\">paralysie unilatérale du nerf vague</span></span> ; <span><span class=\"nc-orange_bg\">myopathie</span></span> ; <span><span class=\"nc-red_bg\">syndrome pseudobulbaire</span></span><span class=\"nc-red_bg\"> d'origine vasculaire</span></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Appréciation de la gravité</h4>\n      <div class=\"callout callout-danger\"><strong><span>Signes de gravité</span> 🚩</strong> — <span><span class=\"nc-yellow_bg\">fausses routes</span></span><span class=\"nc-yellow_bg\"> alimentaires ou salivaires</span> ; <span>pneumopathies d'inhalation à répétition</span> ; <span><span class=\"nc-red_bg\">dénutrition</span></span> ; <span><span class=\"nc-red_bg\">déshydratation</span></span> ; <span><span class=\"nc-brown_bg\">otalgie réflexe</span></span> (<span>drapeau rouge</span> devant faire rechercher un cancer).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 298 — Tumeur cavité buccale-nasosinusienne-cavum-VADS · 98 — <span class=\"nc-orange_bg\">Myasthénie</span> · 106 — <span class=\"nc-red_bg\">Parkinson</span></em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Le transit baryté reste utile dans certaines indications, notamment diverticule de Zenker ou <span class=\"nc-red nc-bold\">achalasie</span>. La vidéofluoroscopie étudie la déglutition dans des conditions adaptées ; elle n’impose pas systématiquement le décubitus. L’IRM n’est pas un examen de routine de toute <span class=\"nc-yellow_bg\">dysphagie</span> inexpliquée.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.snfge.org/tncd/cancer-loesophage-jonction-oeso-gastrique\" target=\"_blank\" rel=\"noopener noreferrer\">TNCD · œsophage et jonction œsogastrique</a></li><li><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC12269739/\" target=\"_blank\" rel=\"noopener noreferrer\">UEG–ESNM · dysphagies, recommandations 2025</a></li></ul></details>","frequence":0},{"id":"273-8","rang":"B","rubrique":"Contenu multimédia","titre":"Radiographie typique d’un corps étranger pharyngo-œsophagien","contenu":"<div class=\"notion-course\"><p>Devant la suspicion d'un <span>corps <span class=\"nc-red nc-bold\">étranger</span> pharyngo-œsophagien</span>, l'examen de débrouillage est une <span>radiographie simple sans opacification</span>, réalisée de <strong>face et de profil</strong>. Le corps <span class=\"nc-red nc-bold\">étranger</span> se situe en règle générale dans l'œsophage cervical, en regard du <span>sphincter supérieur de l'œsophage (SSO)</span>.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Aspect radiographique typique</h4>\n      <ul>\n        <li><strong>Corps <span class=\"nc-red nc-bold\">étranger</span> radio-opaque :</strong> situé <span class=\"nc-red nc-bold\">au niveau cervical</span> ou déjà en aval ; de profil, il se projette <span>en arrière de la trachée, en position prérachidienne</span>.</li>\n        <li><strong>Pile bouton</strong> (corps <span class=\"nc-red nc-bold\">étranger</span> dangereux) : aspect caractéristique en <span>doubles contours</span> sur la <span>radiographie</span>.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Signes radiographiques de complication</h4>\n      <p>Une <span class=\"nc-red_bg\">perforation avec médiastinite</span> se traduit par :</p>\n      <ul>\n        <li><span>Épanchement gazeux</span></li>\n        <li><span>Épaississement des parties molles cervico-médiastinales</span></li>\n        <li><span>Signe de Minigerode</span> : image claire pré-vertébrale sur la <span>radiographie</span> de profil</li>\n        <li><span>Emphysème médiastinal</span> sous forme d'une ligne bordante de la silhouette cardiaque</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Pile bouton — <span>urgence</span> 🚩</strong> — risque de <span><span class=\"nc-red nc-bold\">corrosion chimique</span></span> conduisant à une <span><span class=\"nc-red nc-bold\">perforation par nécrose</span></span> (<span class=\"nc-red_bg\">médiastinite</span>, <span>hémorragie massive</span> par <span>lésion</span> vasculaire). L'aspect en doubles contours et l'interrogatoire orientent le diagnostic ; extraction en urgence.</div>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/273/rp-corps-etranger-pharyngo-oesophagien.png\" alt=\"Radiographie de thorax de face montrant une formation radio-opaque enclavée dans le tiers supérieur de l&#x27;œsophage, avec aspect de double contour correspondant à une pile bouton et bords rognés évoquant une érosion\" loading=\"lazy\">\n        <figcaption><span>Radiographie de thorax de face</span> — <span>corps étranger pharyngo-œsophagien</span>. Formation <span>radio-opaque enclavée dans le tiers supérieur de l'œsophage</span> ; l'<span>aspect de double contour</span> correspond à une <span>pile bouton</span>, et l'<span>aspect rogné des bords</span> évoque une <span>érosion</span> devant faire rechercher en urgence une <span>œsophagite caustique</span>. Indication à une <span>fibroscopie en urgence</span> (recommandations HAS 2022). Source : banque imagerie « Imagerie à connaître » (item 273).</figcaption>\n      </figure></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://www.snfge.org/tncd/cancer-loesophage-jonction-oeso-gastrique\" target=\"_blank\" rel=\"noopener noreferrer\">TNCD · œsophage et jonction œsogastrique</a></li><li><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC12269739/\" target=\"_blank\" rel=\"noopener noreferrer\">UEG–ESNM · dysphagies, recommandations 2025</a></li></ul></details>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/esophageal-foreign-bodies","label":"Radiopaedia : Esophageal foreign bodies"},{"href":"https://radiopaedia.org/articles/zenker-diverticulum-1","label":"Radiopaedia : Zenker diverticulum 1"},{"href":"https://radiopaedia.org/articles/achalasia","label":"Radiopaedia : Achalasia"}]}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré</strong></p><ul><li><span class=\"kw-alerte\">toute dysphagie = lésionnelle (cancer œsophage) jusqu'à preuve du contraire</span> → exploration <strong>non différable</strong></li></ul><p><strong><span class=\"kw-clinique\">Dysphagie</span> chronique</strong></p><p><span class=\"kw-imagerie\">EOGD</span> semi-urgente (<span class=\"kw-chiffre\">≤ 2 semaines</span> si suspicion <span class=\"kw-etio\">tumorale</span> ou <span class=\"kw-clinique\">AEG</span>)</p><p><strong>Corps étranger pharyngo-œsophagien</strong></p><p>extraction <span class=\"kw-alerte\">en urgence</span> par <span class=\"kw-imagerie\">endoscopie</span> sous AG (tube rigide)</p><p><strong>Pile bouton</strong></p><p>extraction <strong>immédiate</strong></p><ul><li><span class=\"kw-alerte\">urgence absolue</span></li><li>risque de <span class=\"kw-alerte\">corrosion chimique</span> et de <span class=\"kw-alerte\">perforation par nécrose</span></li></ul><p><strong>Ingestion caustique</strong></p><ul><li><span class=\"kw-imagerie\">TDM</span> entre <span class=\"kw-chiffre\">3-6 h</span> post-ingestion</li><li><span class=\"kw-ci\">pas de SNG, pas de lavage, pas de vomissements, pas de boisson/lait/charbon</span></li></ul><p><strong>Fausses routes massives + <span class=\"kw-alerte\">détresse</span> respiratoire</strong></p><p>protection des voies aériennes</p><ul><li><span class=\"kw-alerte\">urgence vitale</span></li></ul>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-clinique\">dysphagie</span> chronique sans <span class=\"kw-alerte\">signe de gravité</span> → consultation <span class=\"kw-def\">gastro-entérologue</span> pour <span class=\"kw-imagerie\">EOGD</span> programmée.</p><p><strong>Avis spécialisé associé :</strong> <span class=\"kw-def\">ORL</span> si dysphagie oropharyngée ; <span class=\"kw-def\">neurologue</span> si signes neuro (Parkinson, <span class=\"kw-alerte\">AVC</span>, myasthénie, SLA) ; <span class=\"kw-def\">oncologue</span> si tumeur retrouvée.</p><p><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> <span class=\"kw-alerte\">suspicion tumorale</span>, <span class=\"kw-alerte\">dénutrition</span>/<span class=\"kw-alerte\">déshydratation</span> sévère, dysphagie aiguë inexpliquée, <span class=\"kw-etio\">diverticule de Zenker</span> symptomatique avec retentissement.</p><p><strong><span class=\"kw-alerte\">Réanimation</span> :</strong> <span class=\"kw-alerte\">caustique grade 3</span> (<span class=\"kw-clinique\">nécrose</span> transmurale), <span class=\"kw-alerte\">médiastinite</span> sur perforation, <span class=\"kw-alerte\">choc septique</span>, <span class=\"kw-alerte\">détresse respiratoire</span> sur fausses routes massives.</p><p><strong>Bloc opératoire :</strong> extraction CE œsophagien sous AG par tube rigide ; abord cervical gauche + <span class=\"kw-ttt\">drainage</span> si médiastinite.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Fausses routes</span> alimentaires ou salivaires (silencieuses ou patentes)</li><li><span class=\"kw-alerte\">Pneumopathies d'inhalation à répétition</span> ± <span class=\"kw-clinique\">fièvre récurrente inexpliquée</span></li><li><span class=\"kw-alerte\">AEG</span> · <span class=\"kw-alerte\">perte de poids</span> · <span class=\"kw-alerte\">dénutrition</span> · <span class=\"kw-alerte\">déshydratation</span></li><li><span class=\"kw-alerte\">Otalgie réflexe</span> → rechercher un <span class=\"kw-etio\">cancer du pharynx</span> ou du <span class=\"kw-etio\">vestibule laryngé</span></li><li><span class=\"kw-alerte\">Stase salivaire</span> = très bon signe d'<strong>organicité</strong> (baisse propulsion pharyngée ou trouble relaxation SSO)</li><li><span class=\"kw-clinique\">Dysphagie douloureuse (odynophagie)</span> + <span class=\"kw-alerte\">AEG</span> → suspecter <span class=\"kw-etio\">cancer œsophage</span> ou <span class=\"kw-etio\">œsophagite sévère</span></li><li><span class=\"kw-clinique\">Dysphonie</span> et/ou <span class=\"kw-clinique\">dyspnée</span> → <span class=\"kw-alerte\">paralysie laryngée</span> (compression du <span class=\"kw-def\">X</span>) ou obstacle laryngo-trachéal</li><li><span class=\"kw-clinique\">Régurgitations nasales</span>, <span class=\"kw-clinique\">toux aux repas</span>, <span class=\"kw-clinique\">voix gargouillante/humide</span> = défaut de protection des voies respiratoires</li><li>Aggravation <span class=\"kw-alerte\">croissante</span> avec prédominance sur <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">solides</span> → <span class=\"kw-etio\">tumoral</span> jusqu'à preuve du contraire</li><li>Corps étranger : <span class=\"kw-alerte\">pile bouton</span> (aspect en <span class=\"kw-radio\">doubles contours</span>) — perforation imminente par corrosion</li><li>Médiastinite sur perforation : <span class=\"kw-alerte\">douleur</span> + <span class=\"kw-alerte\">empâtement cervical</span> + <span class=\"kw-alerte\">emphysème sous-cutané</span> + <span class=\"kw-clinique\">fièvre</span> ± <span class=\"kw-radio\">signe de Minigerode</span></li></ul>","principes":"<p><strong>Règle d'or :</strong> toute <span class=\"kw-clinique\">dysphagie</span> est <span class=\"kw-alerte\">lésionnelle jusqu'à preuve du contraire</span> → <span class=\"kw-imagerie\">EOGD</span> + <span class=\"kw-bio\">biopsies</span> systématiques, <strong>même si muqueuse macroscopiquement normale</strong> (recherche d'<span class=\"kw-etio\">œsophagite à éosinophiles</span>).</p><ul><li><strong>Bilan systématique en <span class=\"kw-chiffre\">1ère intention</span> :</strong> <span class=\"kw-imagerie\">EOGD</span> + <span class=\"kw-bio\">biopsies œsophagiennes</span> étagées, quel que soit le type de <span class=\"kw-clinique\">dysphagie</span></li><li><strong><span class=\"kw-clinique\">Dysphagie</span> oropharyngée :</strong> bilan <span class=\"kw-def\">ORL</span> (nasofibroscopie de déglutition, <span class=\"kw-imagerie\">vidéo-fluoroscopie</span> = gold standard, <span class=\"kw-imagerie\">panendoscopie ORL</span> si suspicion VADS) + bilan <span class=\"kw-def\">neurologique</span> (<span class=\"kw-imagerie\">IRM tronc cérébral</span> si pas d'étiologie)</li><li><strong><span class=\"kw-clinique\">Dysphagie</span> œsophagienne avec <span class=\"kw-clinique\">lésion</span> :</strong> traitement étiologique selon la cause (oncologique, <span class=\"kw-ttt\">dilatation endoscopique</span> pour sténoses bénignes, <span class=\"kw-ttt\">IPP</span> pour œsophagite peptique)</li><li><strong><span class=\"kw-clinique\">Dysphagie</span> œsophagienne sans <span class=\"kw-clinique\">lésion</span>, biopsies positives :</strong> <span class=\"kw-etio\">œsophagite à éosinophiles</span> → <span class=\"kw-ttt\">corticothérapie locale</span> (<span class=\"kw-ttt\">corticoïdes</span> inhalés à avaler)</li><li><strong><span class=\"kw-clinique\">Dysphagie</span> œsophagienne sans <span class=\"kw-clinique\">lésion</span>, biopsies négatives :</strong> <span class=\"kw-imagerie\">manométrie œsophagienne</span> en ambulatoire (péristaltisme + relaxation SIO)</li><li><span class=\"kw-etio\">Achalasie</span> confirmée → <span class=\"kw-ttt\">dilatation pneumatique du SIO</span>, <span class=\"kw-ttt\">myotomie de Heller</span> ou <span class=\"kw-ttt\">POEM</span> ; <span class=\"kw-ttt\">toxine botulique</span> si CI chirurgicale ; <span class=\"kw-ttt\">inhibiteurs calciques</span> en symptomatique</li><li><span class=\"kw-etio\">Diverticule de Zenker</span> symptomatique → <span class=\"kw-ttt\">myotomie extramuqueuse</span> (voie ouverte) ou <span class=\"kw-ttt\">myotomie transmuqueuse</span> (voie endoscopique)</li><li><span class=\"kw-etio\">Corps étranger œsophagien</span> reconnu → <span class=\"kw-ttt\">extraction sous AG</span> par voie endoscopique avec tubes rigides ; <span class=\"kw-ttt\">abord cervical gauche</span> + <span class=\"kw-ttt\">drainage</span> si médiastinite</li><li><strong>Renutrition / hydratation</strong> parallèles dès qu'il y a retentissement (<span class=\"kw-ttt\">SNG</span>, <span class=\"kw-ttt\">complémentation orale</span>, voire <span class=\"kw-ttt\">gastrostomie</span> si <span class=\"kw-clinique\">dysphagie</span> chronique sévère)</li><li><strong>Caustiques :</strong> <span class=\"kw-ci\">pas de SNG / lavage gastrique / vomissements induits</span> ; <span class=\"kw-ci\">pas de boisson, lait, charbon activé</span> ; position proclive 45° + réa + <span class=\"kw-imagerie\">TDM 3-6 h</span> + <span class=\"kw-def\">classification</span> radiologique grades 1-2-3 conditionnant la suite</li></ul>","suivi":"<p><strong>Nutritionnel :</strong> <span class=\"kw-clinique\">poids</span>, <span class=\"kw-bio\">albumine</span>, <span class=\"kw-bio\">préalbumine</span>, <span class=\"kw-clinique\">IMC</span> ; consultation <span class=\"kw-def\">diététicienne</span> ; adaptation des textures si <span class=\"kw-clinique\">dysphagie</span> oropharyngée chronique.</p><p><strong>Orthophonie :</strong> rééducation déglutition (post-AVC, Parkinson, troubles oropharyngés chroniques).</p><p><strong><span class=\"kw-imagerie\">EOGD</span> de contrôle :</strong> selon étiologie — <span class=\"kw-etio\">œsophagite peptique</span> (recherche endobrachyœsophage à <span class=\"kw-chiffre\">2 mois</span> de traitement), <span class=\"kw-etio\">œsophagite à éosinophiles</span> (réponse à <span class=\"kw-ttt\">corticothérapie</span>), <span class=\"kw-etio\">cancer œsophage</span> (bilan &amp; <span class=\"kw-def\">suivi</span> onco), <span class=\"kw-etio\">sténose caustique</span> (Zargar endoscopique au décours).</p><p><strong>Prévention <span class=\"kw-clinique\">pneumopathie d'inhalation</span> :</strong> <span class=\"kw-ttt\">vaccin antipneumococcique</span> + <span class=\"kw-ttt\">antigrippal</span> ; hygiène buccale ; positionnement aux repas.</p><p><strong>Après détorsion <span class=\"kw-etio\">diverticule de Zenker</span> ou <span class=\"kw-etio\">achalasie</span> traitée :</strong> <span class=\"kw-def\">surveillance</span> clinique du <span class=\"kw-def\">score d'Eckardt</span> (dysphagie, régurgitations, douleur, perte de poids) à distance.</p>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/esophageal-foreign-bodies","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/zenker-diverticulum-1","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/achalasia","label":"radiopaedia.org"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Dysphagie confirmée à l'interrogatoire — Préalable : éliminer odynophagie, globus, anorexie, satiété précoce, rumination","detail":"<h4>Démarche diagnostique — <span class=\"kw-clinique\">Dysphagie</span> — Siège → <span class=\"kw-imagerie\">EOGD</span> systématique → mécanisme → étiologie</h4>","branches":[{"to":"q-oropharyngee","label":"Siège cervical / fausses routes / voix gargouillante","color":"amber"},{"to":"q-eogd","label":"Siège rétrosternal / blocage après déglutition","color":"blue"}]},{"id":"q-oropharyngee","kind":"decision","label":"Dysphagie OROPHARYNGÉE — Causes ORL ou neurologiques · Bilan : ORL complet + neuro + nasofibroscopie + vidéo-fluoroscopie","branches":[{"to":"t-vads","label":"Otalgie réflexe / AEG / tabac-alcool","color":"red"},{"to":"t-neuro","label":"Syndrome neurologique (AVC, Parkinson, SLA, myasthénie)","color":"amber"},{"to":"t-zenker","label":"Ruminations + régurgitations + bruits hydro-aériques","color":"amber"},{"to":"t-sso","label":"Sténose du SSO / Plummer-Vinson / séquelles caustiques","color":"amber"}]},{"id":"t-vads","kind":"terminal","label":"Cancer des VADS","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Dysphagie oropharyngée</span> + <span class=\"kw-alerte\">otalgie réflexe</span> (<span class=\"kw-alerte\">drapeau rouge</span>)</li><li><span class=\"kw-alerte\">AEG</span>, <span class=\"kw-alerte\">perte de poids</span></li><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-etio\">intoxication alcoolo-tabagique</span></li><li>Localisations : <span class=\"kw-etio\">cancer du pharynx</span>, <span class=\"kw-etio\">larynx</span>, <span class=\"kw-etio\">1/3 supérieur de l'œsophage</span>, <span class=\"kw-etio\">cavité buccale</span> (<span class=\"kw-clinique\">dysphagie</span> tardive)</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Panendoscopie ORL</span> sous AG (indispensable pour le bilan)</li><li><span class=\"kw-imagerie\">TDM cervico-thoracique injectée</span> (extension + recherche compression du X)</li><li><span class=\"kw-bio\">Biopsies</span> sous AG</li><li><span class=\"kw-def\">Bilan d'extension</span> carcinologique standard</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Chirurgie</span> / <span class=\"kw-ttt\">radiothérapie</span> / chimiothérapie selon <span class=\"kw-def\">stade</span>, en <span class=\"kw-def\">RCP</span> oncologique.</li></ul><h4>Renvoi</h4><ul><li>Cf. item <strong>298</strong> — Tumeur cavité buccale-nasosinusienne-cavum-VADS.</li></ul>"},{"id":"t-neuro","kind":"terminal","label":"Cause neurologique","color":"amber","detail":"<h4>Étiologies</h4><ul><li>Maladies neurodégénératives : <span class=\"kw-etio\">Parkinson</span>, <span class=\"kw-etio\">Alzheimer</span>, démence sénile</li><li><span class=\"kw-etio\">AVC</span> (notamment du tronc cérébral)</li><li><span class=\"kw-etio\">SLA</span>, <span class=\"kw-etio\">myasthénie</span>, <span class=\"kw-etio\">myopathie</span></li><li><span class=\"kw-etio\">Paralysie unilatérale du nerf vague (X)</span></li><li><span class=\"kw-etio\">Syndrome pseudobulbaire</span> d'origine vasculaire</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">IRM du tronc cérébral</span> devant <span class=\"kw-clinique\">dysphagie</span> sans étiologie</li><li><span class=\"kw-imagerie\">TDM cervico-thoracique</span> systématique si <span class=\"kw-alerte\">paralysie laryngée</span> (compression du <span class=\"kw-def\">X</span>)</li><li>Bilan neurologique adapté (<span class=\"kw-bio\">EMG</span>, recherche <span class=\"kw-bio\">anticorps anti-récepteurs</span> acétylcholine si myasthénie)</li></ul><h4>Conduite</h4><ul><li>Traitement étiologique de la maladie neurologique</li><li><span class=\"kw-ttt\">Orthophonie</span> : rééducation de la déglutition</li><li>Adaptation des textures (épaississants, eau gélifiée)</li><li><span class=\"kw-ttt\">Gastrostomie</span> si <span class=\"kw-clinique\">dysphagie</span> sévère chronique avec retentissement</li></ul><h4>Renvois</h4><ul><li>Cf. items <strong>98</strong> (Myasthénie), <strong>106</strong> (Parkinson).</li></ul>"},{"id":"t-zenker","kind":"terminal","label":"Diverticule de Zenker","color":"amber","detail":"<h4>Définition</h4><ul><li>Hernie de la face postérieure de la jonction pharyngo-laryngée, <strong>au-dessus du SSO</strong>, se développant vers le médiastin rétro-œsophagien.</li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Dysphagie haute</span></li><li><span class=\"kw-clinique\">Ruminations</span>, <span class=\"kw-clinique\">régurgitations d'aliments non digérés</span> (parfois déclenchées par pression cervicale)</li><li><span class=\"kw-clinique\">Bruits hydro-aériques</span></li><li><span class=\"kw-clinique\">Toux nocturne</span> de décubitus</li><li>Retentissement : <span class=\"kw-alerte\">AEG</span>, <span class=\"kw-alerte\">pneumopathie d'inhalation</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Nasofibroscopie</span> : <strong>signe de la marée pathognomonique</strong> (bouchée disparaît puis réapparaît)</li><li><span class=\"kw-imagerie\">Radio-cinéma de la déglutition</span> : confirme le diagnostic</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Myotomie extramuqueuse</span> (voie ouverte)</li><li>OU <span class=\"kw-ttt\">myotomie transmuqueuse</span> (voie endoscopique)</li></ul>"},{"id":"t-sso","kind":"terminal","label":"Atteinte du SSO","color":"amber","detail":"<h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Achalasie du sphincter supérieur</span> (hypertonie du crico-pharyngien)</li><li><span class=\"kw-etio\">Syndrome de Plummer-Vinson</span> (ou Kelly-Patterson)</li><li><span class=\"kw-etio\">Séquelles d'ingestion de caustique</span></li><li><span class=\"kw-etio\">Compression extrinsèque</span> : volumineux goitre plongeant, anévrisme aorte thoracique, tumeur médiastin, anomalie vertébrale</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">TDM thoracique injectée</span> pour préciser une compression extrinsèque</li><li><span class=\"kw-imagerie\">Manométrie</span> peu performante pour l'étude du SSO</li></ul><h4>Traitement</h4><ul><li>Selon étiologie — <span class=\"kw-ttt\">chirurgie</span> de la cause extrinsèque, <span class=\"kw-ttt\">dilatation</span> ou <span class=\"kw-ttt\">myotomie</span> du crico-pharyngien.</li></ul>"},{"id":"q-eogd","kind":"decision","label":"Dysphagie ŒSOPHAGIENNE → EOGD + biopsies SYSTÉMATIQUES — Biopsies même si muqueuse macroscopiquement normale (œsophagite à éosinophiles)","branches":[{"to":"q-lesion","label":"Lésion macroscopique visible","color":"red"},{"to":"q-biopsies","label":"EOGD macroscopiquement normale","color":"blue"}]},{"id":"q-lesion","kind":"decision","label":"Dysphagie LÉSIONNELLE — Caractériser la lésion","branches":[{"to":"t-cancer-oeso","label":"Ulcéro-bourgeonnante, irrégulière, sténose excentrée","color":"red"},{"to":"t-stenose-benigne","label":"Sténose fibreuse régulière centrée (peptique, caustique, post-radique, Schatzki)","color":"amber"},{"to":"t-oesophagite-medic","label":"Œsophagite sans sténose (médicaments, infections, RGO)","color":"amber"},{"to":"t-compression","label":"Compression extrinsèque (tumeur médiastinale, adénopathies)","color":"red"}]},{"id":"t-cancer-oeso","kind":"terminal","label":"Cancer de l'œsophage","color":"red","detail":"<h4>Aspect <span class=\"kw-imagerie\">EOGD</span></h4><ul><li><span class=\"kw-clinique\">Lésion</span> <strong>ulcéro-bourgeonnante</strong>, <strong>irrégulière</strong></li><li><span class=\"kw-alerte\">Saigne au contact</span></li><li><span class=\"kw-alerte\">Sténose excentrée</span></li><li>Types : <span class=\"kw-etio\">carcinome épidermoïde</span> (<span class=\"kw-etio\">alcool</span>-tabac) · <span class=\"kw-etio\">adénocarcinome</span> (endobrachyœsophage)</li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Dysphagie</span> aux <span class=\"kw-alerte\">solides</span>, d'<span class=\"kw-alerte\">aggravation progressive</span></li><li><span class=\"kw-alerte\">Retentissement sur l'état général</span></li><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-etio\">intoxication alcoolo-tabagique</span></li></ul><h4>Bilan</h4><ul><li><span class=\"kw-bio\">Biopsies multiples étagées</span></li><li><span class=\"kw-imagerie\">Écho-endoscopie haute</span> (bilan local)</li><li><span class=\"kw-imagerie\">TDM-TAP injectée</span> (extension)</li><li>Discussion en <span class=\"kw-def\">RCP</span></li></ul><h4>Renvoi</h4><ul><li>Cf. item <strong>305</strong> — Tumeur de l'œsophage.</li></ul>"},{"id":"t-stenose-benigne","kind":"terminal","label":"Sténose bénigne (non tumorale)","color":"amber","detail":"<h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Sténose peptique</span> (<span class=\"kw-clinique\">RGO</span> chronique → cf item <strong>271</strong>)</li><li><span class=\"kw-etio\">Sténose caustique</span> (séquelle d'ingestion)</li><li><span class=\"kw-etio\">Sténose post-radique</span></li><li><span class=\"kw-etio\">Sténose cicatricielle</span> ou <span class=\"kw-etio\">anastomotique post-œsophagectomie</span></li><li><span class=\"kw-etio\">Anneau de Schatzki</span> (diaphragme du 1/3 inférieur)</li></ul><h4>Aspect <span class=\"kw-imagerie\">EOGD</span></h4><ul><li>Sténose <strong>fibreuse</strong>, <strong>régulière</strong>, <strong>centrée</strong> (contraste avec la sténose excentrée <span class=\"kw-etio\">tumorale</span>).</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Dilatation endoscopique</span> (bougies, ballonnets)</li><li><span class=\"kw-ttt\">IPP au long cours</span> si sténose peptique</li><li>Traitement étiologique selon la cause</li><li><span class=\"kw-bio\">Biopsies</span> pour éliminer une néoplasie sous-jacente</li></ul>"},{"id":"t-oesophagite-medic","kind":"terminal","label":"Œsophagite (sans sténose)","color":"amber","detail":"<h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Médicamenteuse</span> : <span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">biphosphonates</span>, <span class=\"kw-ttt\">tétracyclines</span>, <span class=\"kw-ttt\">chlorure de potassium</span></li><li><span class=\"kw-etio\">Infectieuse</span> chez l'immunodéprimé : <span class=\"kw-etio\">Candida</span>, <span class=\"kw-etio\">CMV</span>, <span class=\"kw-etio\">HSV</span></li><li><span class=\"kw-etio\">Peptique</span> (<span class=\"kw-clinique\">RGO</span> chronique → cf item <strong>271</strong>)</li></ul><h4>Symptôme prédominant</h4><ul><li><span class=\"kw-clinique\">Odynophagie</span> (déglutition douloureuse), parfois <span class=\"kw-clinique\">dysphagie</span> associée.</li></ul><h4>Traitement</h4><ul><li>Arrêt du médicament en cause + conseils de prise (debout, grand verre d'eau)</li><li><span class=\"kw-ttt\">IPP</span> si œsophagite peptique</li><li><span class=\"kw-ttt\">Antifongique</span> (<span class=\"kw-ttt\">fluconazole</span>) / <span class=\"kw-ttt\">antiviral</span> si cause infectieuse</li></ul>"},{"id":"t-compression","kind":"terminal","label":"Compression extrinsèque","color":"red","detail":"<h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Carcinome bronchopulmonaire</span></li><li><span class=\"kw-etio\">Tumeurs ou adénopathies médiastinales</span></li><li><span class=\"kw-etio\">Volumineuse hernie hiatale par roulement</span></li><li><span class=\"kw-etio\">Diverticule œsophagien</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">TDM-TAP injectée</span> avec opacification digestive haute (examen clé)</li><li><span class=\"kw-imagerie\">Écho-endoscopie haute</span> si suspicion de <span class=\"kw-etio\">tumeur sous-muqueuse</span> (caractérisation + <span class=\"kw-ttt\">ponction</span>)</li></ul><h4>Traitement</h4><ul><li>Étiologique — chirurgical / oncologique selon la cause comprimante.</li></ul>"},{"id":"q-biopsies","kind":"decision","label":"Résultat des biopsies œsophagiennes ? — Biopsies systématiques — clé du diagnostic","branches":[{"to":"t-eosino","label":"Infiltrat à PNE (> 15/champ x400)","color":"green"},{"to":"q-manometrie","label":"Biopsies normales → manométrie œsophagienne","color":"blue"}]},{"id":"t-eosino","kind":"terminal","label":"Œsophagite à éosinophiles","color":"green","detail":"<h4><span class=\"kw-def\">Terrain</span></h4><ul><li>Enfant ou sujet jeune, prédominance <strong>masculine</strong></li><li><span class=\"kw-etio\">Terrain atopique</span> (asthme, <span class=\"kw-clinique\">eczéma</span>) dans <span class=\"kw-chiffre\">50-80 %</span> des cas</li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Dysphagie</span> avec <span class=\"kw-clinique\">sensation de blocage alimentaire</span>, parfois <strong>intermittente</strong>.</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Hyperéosinophilie sanguine</span> possible</li><li><span class=\"kw-imagerie\">EOGD</span> : <strong>souvent normale</strong>, parfois anomalies (<span class=\"kw-radio\">dépôts granités blanchâtres</span>, <span class=\"kw-radio\">stries linéaires verticales</span>, <span class=\"kw-radio\">aspect pseudo-trachéal</span>)</li><li><span class=\"kw-bio\">Histologie</span> : <strong>infiltrat à PNE <span class=\"kw-chiffre\">> 15</span>/champ au grossissement x 400</strong> = diagnostic</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Corticothérapie locale</span> (<span class=\"kw-ttt\">corticoïdes</span> inhalés à <strong>avaler</strong>)</li><li>Réponse clinique et histologique évaluée à <span class=\"kw-chiffre\">8-12 semaines</span></li><li>Pas de risque de cancer ; risque de <span class=\"kw-alerte\">sténose</span> et <span class=\"kw-alerte\">perforation</span> en cas d'<span class=\"kw-clinique\">évolution</span></li></ul>"},{"id":"q-manometrie","kind":"decision","label":"Manométrie œsophagienne en 2ᵉ intention — Évalue péristaltisme + relaxation du SIO en ambulatoire","branches":[{"to":"t-achalasie","label":"Absence péristaltisme + défaut relaxation SIO","color":"amber"},{"to":"t-trouble-moteur","label":"Autre trouble moteur primaire (spasmes, marteau-piqueur)","color":"amber"},{"to":"t-trouble-secondaire","label":"Trouble moteur secondaire (sclérodermie, lupus, Gougerot)","color":"amber"},{"to":"t-fonctionnelle","label":"Manométrie normale","color":"green"}]},{"id":"t-achalasie","kind":"terminal","label":"Achalasie","color":"amber","detail":"<h4>Définition</h4><ul><li>Trouble moteur <strong>primitif</strong> de l'œsophage de cause inconnue : <span class=\"kw-alerte\">absence de relaxation du SIO</span> + <span class=\"kw-alerte\">absence de péristaltisme</span> dans le corps.</li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Dysphagie paradoxale</span> (prédomine sur <span class=\"kw-clinique\">les</span> <strong>liquides</strong>), <span class=\"kw-clinique\">capricieuse</span>, intermittente</li><li><span class=\"kw-clinique\">Régurgitations</span> notamment en <strong>décubitus</strong></li><li><span class=\"kw-clinique\">Douleurs rétrosternales constrictives</span> pseudo-angineuses (non liées à l'effort)</li><li><span class=\"kw-alerte\">Amaigrissement</span> quantifié par le <span class=\"kw-def\">score d'Eckardt</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">EOGD</span> : souvent normale au début, ressaut au passage du cardia ; <span class=\"kw-def\">stade</span> évolué = œsophage <span class=\"kw-radio\">dilaté, atone</span> avec résidus</li><li><span class=\"kw-imagerie\">TOGD</span> : <span class=\"kw-radio\">méga-œsophage</span>, cardia en <strong>bec d'oiseau</strong>, stase du PDC dans le 1/3 inférieur</li><li><span class=\"kw-imagerie\">Manométrie</span> : Type 1 (défaut SIO isolé) · Type 2 (pressurisation pan-œsophagienne) · Type 3 (contractions prématurées spastiques <span class=\"kw-chiffre\">≥ 20 %</span>)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Dilatation pneumatique du SIO</span> (endoscopique)</li><li><span class=\"kw-ttt\">Myotomie de Heller</span> (chirurgicale) + antireflux</li><li><span class=\"kw-ttt\">POEM</span> (Per-Oral Endoscopic Myotomy)</li><li><span class=\"kw-ttt\">Toxine botulique</span> si CI chirurgicale (effet transitoire)</li><li><span class=\"kw-ttt\">Inhibiteurs calciques</span> / <span class=\"kw-ttt\">dérivés nitrés</span> en symptomatique</li></ul><h4><span class=\"kw-def\">Diagnostic différentiel</span></h4><ul><li><span class=\"kw-etio\">Adénocarcinome du cardia</span> (<span class=\"kw-clinique\">achalasie</span> <strong>secondaire</strong>) → toujours faire <span class=\"kw-imagerie\">EOGD</span> + biopsies</li><li><span class=\"kw-etio\">Maladie de Chagas</span> (Trypanosoma cruzi, Amérique du Sud)</li></ul>"},{"id":"t-trouble-moteur","kind":"terminal","label":"Autre trouble moteur œsophagien primaire","color":"amber","detail":"<h4>Entités</h4><ul><li><span class=\"kw-etio\">Spasmes œsophagiens</span> (contractions simultanées non péristaltiques)</li><li><span class=\"kw-etio\">Œsophage hypercontractile</span> ou « marteau-piqueur » (jackhammer)</li><li><span class=\"kw-etio\">Péristaltisme œsophagien inefficace ou absent</span> (avec relaxation SIO normale)</li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Dysphagie</span> + douleurs rétrosternales, fluctuantes, sans aggravation progressive.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Inhibiteurs calciques</span> · <span class=\"kw-ttt\">dérivés nitrés</span></li><li><span class=\"kw-ttt\">IPP</span> (souvent associés à un <span class=\"kw-clinique\">RGO</span>)</li><li>Prise en charge symptomatique adaptée</li></ul>"},{"id":"t-trouble-secondaire","kind":"terminal","label":"Trouble moteur secondaire","color":"amber","detail":"<h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Sclérodermie</span> (atteinte œsophagienne très fréquente)</li><li><span class=\"kw-etio\">Dermatomyosite</span></li><li><span class=\"kw-etio\">Lupus érythémateux disséminé</span></li><li><span class=\"kw-etio\">Syndrome de Gougerot-Sjögren</span></li><li><span class=\"kw-etio\">Myopathies</span>, <span class=\"kw-etio\">paranéoplasique</span></li></ul><h4>Conduite</h4><ul><li>Diagnostic et prise en charge de la <strong>maladie générale</strong></li><li><span class=\"kw-ttt\">IPP</span> car <span class=\"kw-clinique\">RGO</span> souvent associé (hypotonie SIO)</li><li><span class=\"kw-def\">Surveillance</span> des complications œsophagiennes</li></ul>"},{"id":"t-fonctionnelle","kind":"terminal","label":"Dysphagie fonctionnelle","color":"green","detail":"<h4>Définition</h4><ul><li><span class=\"kw-def\">Diagnostic d'élimination</span> — bilan complet négatif (<span class=\"kw-imagerie\">EOGD</span> + biopsies + manométrie tous normaux).</li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Dysphagie</span> sans support organique ni moteur, souvent fluctuante.</li></ul><h4>Conduite</h4><ul><li>Réassurance, explication</li><li>Prise en charge symptomatique (modifications alimentaires)</li><li>Consultation psychologique selon contexte</li><li><span class=\"kw-ttt\">Antidépresseurs tricycliques</span> à faible dose si gêne importante</li></ul>"}]},"cards":[{"i":"3a869bcd9ccf","n":273,"o":"273-1","u":"Définition","t":"Connaître la définition de la dysphagie","q":"Quels sont les diagnostics différentiels principaux à écarter face à une suspicion de dysphagie, en l'absence de blocage alimentaire ?","a":"<div class=\"notion-course\"><ul><li>L'<strong><span class=\"nc-blue_bg\">odynophagie</span></strong> (<span class=\"nc-blue_bg\">douleur</span> sans obstacle)</li><li>Le <strong>globus hystericus</strong> (sensation de compression cervicale liée à l'angoisse)</li><li>L'<strong>anorexie</strong> (perte d'appétit)</li><li>La <strong>satiété précoce</strong> (faim rapidement coupée sans blocage)</li><li>La rumination correspond à une régurgitation répétée sans effort de vomissement ; elle ne doit pas être décrite comme nécessairement volontaire.</li></ul></div>"},{"i":"45b04f845e5c","n":273,"o":"273-1","u":"Définition","t":"Connaître la définition de la dysphagie","q":"Quelle est la définition de la dysphagie ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-blue_bg\">dysphagie</span> est définie comme une <strong><span class=\"nc-blue_bg\">sensation de</span> <span class=\"nc-blue_bg nc-bold\">gêne</span> <span class=\"nc-blue_bg\">ou d'</span><span class=\"nc-blue_bg nc-bold\">obstacle</span> <span class=\"nc-blue_bg\">à la progression du bol alimentaire</span></strong>, survenant <span class=\"nc-red nc-bold\">au cours de la déglutition</span>. C'est la notion de <strong>blocage du transit alimentaire</strong> qui la caractérise.</p></div>"},{"i":"f8edf0928366","n":273,"o":"273-1","u":"Définition","t":"Connaître la définition de la dysphagie","q":"Comment distinguer la dysphagie de l'odynophagie ?","a":"<div class=\"notion-course\"><p>L'<strong><span class=\"nc-blue_bg\">odynophagie</span></strong> est une <strong><span class=\"nc-blue_bg\">douleur</span> ressentie lors de la progression des aliments</strong> dans l'œsophage, mais <strong><span class=\"nc-red nc-bold\">sans sensation de blocage</span></strong>, à la différence de la <span class=\"nc-blue_bg\">dysphagie</span> où il y a un <span class=\"nc-blue_bg nc-bold\">obstacle</span>. Cependant, les deux peuvent coexister (on parle alors de « <span class=\"nc-blue_bg\">dysphagie</span> douloureuse ») suggérant une <span class=\"nc-orange nc-bold\">infection</span>, une œsophagite ou une <span class=\"nc-orange nc-bold\">tumeur</span>.</p></div>"},{"i":"4073ddd36be6","n":273,"o":"273-2","u":"Définition","t":"Connaître les deux types de dysphagie","q":"Selon le mécanisme, quels sont les deux types de dysphagie et leurs caractéristiques principales ?","a":"<div class=\"notion-course\">Il existe deux types de dysphagie selon le mécanisme :\n<ul>\n<li>La <strong><span class=\"nc-brown_bg\">dysphagie lésionnelle</span></strong> : elle est liée à une <strong>lésion organique</strong> œsophagienne ou à une <span class=\"nc-red_bg\">compression extrinsèque</span>.</li>\n<li>La <strong><span class=\"nc-brown_bg\">dysphagie fonctionnelle</span></strong> (ou non lésionnelle) : <strong>aucune lésion n'est identifiée</strong> ; elle est due à une anomalie de la dynamique propulsive du bol alimentaire.</li>\n</ul></div>"},{"i":"88aea8784aa8","n":273,"o":"273-2","u":"Définition","t":"Connaître les deux types de dysphagie","q":"Selon la localisation, quels sont les deux types de dysphagie et leurs caractéristiques principales ?","a":"<div class=\"notion-course\">Il existe deux types de dysphagie selon la localisation :\n<ul>\n<li>La <strong>dysphagie œsophagienne</strong> : <span class=\"nc-blue_bg\">sensation de</span> blocage du bol alimentaire <span class=\"nc-red nc-bold\">au niveau </span><strong><span class=\"nc-red nc-bold\">rétrosternal</span></strong>, après le déclenchement de la déglutition.</li>\n<li>La <strong><span class=\"nc-orange_bg\">dysphagie oropharyngée</span></strong> : difficulté à initier la déglutition et à propulser le bol dans l'œsophage, gêne ressentie <span class=\"nc-red nc-bold\">au niveau </span><strong><span class=\"nc-red nc-bold\">cervical</span></strong>. Les causes sont essentiellement <span class=\"nc-orange nc-bold\">ORL</span> ou neurologiques.</li>\n</ul></div>"},{"i":"0bb941a29ae1","n":273,"o":"273-3","u":"Diagnostic positif","t":"Connaître les éléments à l’interrogatoire orientant vers une dysphagie lésionnelle ou non lésionnelle","q":"Quels sont les signes de gravité à rechercher devant toute dysphagie ?","a":"<div class=\"notion-course\"><p>Les signes de gravité à rechercher devant toute <span class=\"nc-blue_bg\">dysphagie</span> sont :</p><ul><li>Les <strong><span class=\"nc-purple_bg\">infections pulmonaires</span></strong> ou pneumopathies à répétition, témoignant de <span class=\"nc-blue_bg\">fausses routes</span>.</li><li>Une <strong>perte de poids</strong>.</li><li>Une <strong>dénutrition</strong>.</li><li>Une <strong>déshydratation</strong>.</li></ul><p>Toute <span class=\"nc-blue_bg\">dysphagie</span> doit être considérée comme lésionnelle (cancer de l'œsophage) jusqu'à preuve du contraire, rendant l'<strong><span class=\"nc-yellow_bg\">endoscopie</span> œso-gastro-duodénale avec biopsies systématique</strong>.</p></div>"},{"i":"4778810b1124","n":273,"o":"273-3","u":"Diagnostic positif","t":"Connaître les éléments à l’interrogatoire orientant vers une dysphagie lésionnelle ou non lésionnelle","q":"Quels éléments de l'interrogatoire orientent vers une dysphagie non lésionnelle ou fonctionnelle ?","a":"<div class=\"notion-course\"><p>L'orientation vers une <span class=\"nc-yellow_bg\">dysphagie</span> non lésionnelle (ou fonctionnelle) est suggérée par :</p><ul><li>Une dysphagie prédominant sur les <strong><span class=\"nc-red nc-bold\">liquides</span></strong>.</li><li>Une <span class=\"nc-yellow_bg\">dysphagie</span> <strong><span class=\"nc-red nc-bold\">paradoxale</span></strong> (prédominant sur les <span class=\"nc-red nc-bold\">liquides</span>), classique de l'<span class=\"nc-red nc-bold\">achalasie</span>.</li></ul></div>"},{"i":"cbd41c3702c6","n":273,"o":"273-3","u":"Diagnostic positif","t":"Connaître les éléments à l’interrogatoire orientant vers une dysphagie lésionnelle ou non lésionnelle","q":"Quels éléments de l'interrogatoire orientent vers une dysphagie lésionnelle ?","a":"<div class=\"notion-course\"><p>L'orientation vers une <span class=\"nc-brown_bg\">dysphagie lésionnelle</span> est suggérée par :</p><ul><li>Une <strong>aggravation croissante</strong> de la dysphagie, évoquant une pathologie tumorale.</li><li>Une dysphagie prédominant sur les <strong><span class=\"nc-red nc-bold\">solides</span></strong>.</li><li>La présence d'une <strong><span class=\"nc-yellow_bg\">stase salivaire</span></strong>, signe d'organicité.</li><li>Une <strong><span class=\"nc-brown_bg\">dysphagie douloureuse</span></strong><span class=\"nc-brown_bg\"> (odynophagie)</span>.</li><li>Des <strong>symptômes associés</strong> comme une <span class=\"nc-brown_bg\">dysphonie</span>, une <span class=\"nc-brown_bg\">dyspnée</span> (<span class=\"nc-orange nc-bold\">paralysie laryngée</span>, <span class=\"nc-orange nc-bold\">obstacle laryngo-trachéal</span>) ou une <span class=\"nc-brown_bg\">otalgie réflexe</span> (cancer du <span class=\"nc-red nc-bold\">pharynx</span>/<span class=\"nc-red nc-bold\">larynx</span>).</li><li>Des <strong>antécédents</strong> d'intoxication alcoolo-tabagique.</li></ul></div>"},{"i":"776ad99877db","n":273,"o":"273-4","u":"Examens complémentaires","t":"Connaître l’examen complémentaire non biologique à effectuer en première intention devant une dysphagie","q":"Quel est l'intérêt principal de l'EOGD en cas de dysphagie ?","a":"<div class=\"notion-course\"><p>L'EOGD permet de <strong>visualiser directement la muqueuse œsophagienne, gastrique et duodénale</strong> et d'effectuer des <strong>biopsies</strong>.</p></div>"},{"i":"d1e3474a012c","n":273,"o":"273-4","u":"Examens complémentaires","t":"Connaître l’examen complémentaire non biologique à effectuer en première intention devant une dysphagie","q":"Quel est l'examen complémentaire non biologique de première intention à réaliser devant toute dysphagie, quel que soit son type ?","a":"<div class=\"notion-course\"><p>L'<strong><span class=\"nc-yellow_bg\">endoscopie</span> œso-gastro-duodénale (EOGD)</strong> est l'examen clé de première intention devant toute <span class=\"nc-blue_bg\">dysphagie</span>.</p></div>"},{"i":"d586e9850400","n":273,"o":"273-4","u":"Examens complémentaires","t":"Connaître l’examen complémentaire non biologique à effectuer en première intention devant une dysphagie","q":"Pourquoi des biopsies œsophagiennes sont-elles systématiques lors d'une EOGD pour dysphagie, même si la muqueuse est macroscopiquement normale ?","a":"<div class=\"notion-course\"><ul><li>Les biopsies sont indispensables pour rechercher une <strong>œsophagite à éosinophiles</strong>, une cause fréquente de <span class=\"nc-yellow_bg\">dysphagie</span> où la muqueuse peut apparaître macroscopiquement normale.</li><li>Une muqueuse d'aspect normal à l'<span class=\"nc-yellow_bg\">endoscopie</span> n'élimine donc pas cette pathologie.</li></ul></div>"},{"i":"ddd9fb4b901f","n":273,"o":"273-4","u":"Examens complémentaires","t":"Connaître l’examen complémentaire non biologique à effectuer en première intention devant une dysphagie","q":"Quels éléments, observés lors d'une EOGD, peuvent évoquer un trouble moteur œsophagien chez un patient présentant une dysphagie ?","a":"<div class=\"notion-course\"><p>Une <strong>sensation de ressaut</strong> au passage de l'endoscope à travers la jonction œso-gastrique est évocatrice d'un <span class=\"nc-orange nc-bold\">trouble moteur</span> œsophagien.</p></div>"},{"i":"023478f3429c","n":273,"o":"273-6","u":"Etiologies","t":"Connaître les principales étiologies de dysphagie lésionnelle (tumorale ou non tumorale) et non lésionnelle","q":"Quelles sont les principales étiologies des dysphagies non lésionnelles ?","a":"<div class=\"notion-course\"><p>Les principales étiologies des dysphagies non lésionnelles se divisent en :</p><ul><li><strong>Troubles moteurs primaires</strong> : <strong><span class=\"nc-red nc-bold\">achalasie</span></strong> (absence de péristaltisme + défaut de relaxation du SIO), spasmes œsophagiens, œsophage hypercontractile « <strong><span class=\"nc-red nc-bold\">marteau-piqueur</span></strong> », péristaltisme inefficace ou absent.</li><li><strong>Troubles moteurs secondaires</strong> : associés à des maladies systémiques comme la <strong><span class=\"nc-orange_bg\">sclérodermie</span></strong>, la <span class=\"nc-orange_bg\">dermatomyosite</span>, le <span class=\"nc-orange_bg\">lupus</span>, le syndrome de Gougerot-Sjögren, la <span class=\"nc-orange_bg\">myopathie</span>.</li><li>La <strong><span class=\"nc-brown_bg\">dysphagie fonctionnelle</span></strong> : il s'agit d'un diagnostic d'élimination, après un bilan négatif.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Une <span class=\"nc-orange_bg\">dysphagie oropharyngée</span> oriente d’abord vers l’évaluation de la déglutition et des voies aériennes ; une <span class=\"nc-yellow_bg\">dysphagie</span> œsophagienne vers l’<span class=\"nc-yellow_bg\">endoscopie</span> avec biopsies, puis manométrie si indiquée. Un <span class=\"nc-orange nc-bold\">trouble moteur</span> peut constituer une maladie organique sans <span class=\"nc-blue_bg nc-bold\">obstacle</span> visible.</li></ul></div></div>"},{"i":"2d3a98af9207","n":273,"o":"273-6","u":"Etiologies","t":"Connaître les principales étiologies de dysphagie lésionnelle (tumorale ou non tumorale) et non lésionnelle","q":"Quelles sont les causes non tumorales de sténose œsophagienne pouvant entraîner une dysphagie lésionnelle ?","a":"<div class=\"notion-course\"><p>Les causes non tumorales de sténose œsophagienne entraînant une <span class=\"nc-brown_bg\">dysphagie lésionnelle</span> sont :</p><ul><li>Les sténoses <span class=\"nc-green_bg nc-bold\">fibreuses</span>, <span class=\"nc-green_bg nc-bold\">régulières</span> et <span class=\"nc-green_bg nc-bold\">centrées</span> : <strong>œsophagite à éosinophiles</strong>, <strong>sténose <span class=\"nc-orange nc-bold\">peptique</span></strong>, <strong><span class=\"nc-orange nc-bold\">caustique</span></strong>, <strong><span class=\"nc-orange nc-bold\">post-radique</span></strong>, <strong><span class=\"nc-orange nc-bold\">cicatricielle</span></strong>, <strong>anastomotique</strong> (post-œsophagectomie).</li><li>L'<strong>anneau de Schatzki</strong>.</li><li>Le <strong><span class=\"nc-orange nc-bold\">syndrome de Plummer-Vinson</span></strong>.</li><li>Les <strong><span class=\"nc-orange_bg\">tumeurs sous-muqueuses bénignes</span></strong>.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Une <span class=\"nc-orange_bg\">dysphagie oropharyngée</span> oriente d’abord vers l’évaluation de la déglutition et des voies aériennes ; une <span class=\"nc-yellow_bg\">dysphagie</span> œsophagienne vers l’<span class=\"nc-yellow_bg\">endoscopie</span> avec biopsies, puis manométrie si indiquée. Un <span class=\"nc-orange nc-bold\">trouble moteur</span> peut constituer une maladie organique sans <span class=\"nc-blue_bg nc-bold\">obstacle</span> visible.</li></ul></div></div>"},{"i":"3e84bcfb7d57","n":273,"o":"273-6","u":"Etiologies","t":"Connaître les principales étiologies de dysphagie lésionnelle (tumorale ou non tumorale) et non lésionnelle","q":"Quelles sont les principales étiologies tumorales de la dysphagie œsophagienne ?","a":"<div class=\"notion-course\"><p>Les principales étiologies tumorales de dysphagie œsophagienne sont :</p><ul><li>Le <strong>cancer de l'œsophage</strong> : il s'agit d'une lésion <span class=\"nc-red nc-bold\">ulcéro-bourgeonnante</span>, <span class=\"nc-red nc-bold\">irrégulière</span>, <span class=\"nc-red nc-bold\">saignant au contact</span>, entraînant une <span class=\"nc-red nc-bold\">sténose excentrée</span>. Il peut s'agir de <strong>carcinome épidermoïde</strong> ou d'<strong>adénocarcinome</strong>.</li><li>La <strong><span class=\"nc-red_bg\">compression extrinsèque</span></strong> par une tumeur ou une adénopathie médiastinale, telle qu'un carcinome bronchopulmonaire.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Une <span class=\"nc-orange_bg\">dysphagie oropharyngée</span> oriente d’abord vers l’évaluation de la déglutition et des voies aériennes ; une <span class=\"nc-yellow_bg\">dysphagie</span> œsophagienne vers l’<span class=\"nc-yellow_bg\">endoscopie</span> avec biopsies, puis manométrie si indiquée. Un <span class=\"nc-orange nc-bold\">trouble moteur</span> peut constituer une maladie organique sans <span class=\"nc-blue_bg nc-bold\">obstacle</span> visible.</li></ul></div></div>"},{"i":"4e7ca4388a82","n":273,"o":"273-6","u":"Etiologies","t":"Connaître les principales étiologies de dysphagie lésionnelle (tumorale ou non tumorale) et non lésionnelle","q":"Quelles sont les principales étiologies des œsophagites sans sténose responsables de dysphagie ?","a":"<div class=\"notion-course\"><p>Les principales étiologies des œsophagites sans sténose, dont le symptôme prédominant est l'<strong><span class=\"nc-blue nc-bold\">odynophagie</span></strong>, sont :</p><ul><li>Les inflammations médicamenteuses : <strong><span class=\"nc-pink nc-bold\">AINS</span></strong>, <strong>biphosphonates</strong>, <strong><span class=\"nc-pink nc-bold\">tétracyclines</span></strong>, <strong>chlorure de potassium</strong>.</li><li>Les infections opportunistes chez l'immunodéprimé : <strong>Candida</strong>, <strong>CMV</strong>, <strong>HSV</strong>.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Une <span class=\"nc-orange_bg\">dysphagie oropharyngée</span> oriente d’abord vers l’évaluation de la déglutition et des voies aériennes ; une <span class=\"nc-yellow_bg\">dysphagie</span> œsophagienne vers l’<span class=\"nc-yellow_bg\">endoscopie</span> avec biopsies, puis manométrie si indiquée. Un <span class=\"nc-orange nc-bold\">trouble moteur</span> peut constituer une maladie organique sans <span class=\"nc-blue_bg nc-bold\">obstacle</span> visible.</li></ul></div></div>"},{"i":"ebcf86969f20","n":273,"o":"273-6","u":"Etiologies","t":"Connaître les principales étiologies de dysphagie lésionnelle (tumorale ou non tumorale) et non lésionnelle","q":"Comment différencier cliniquement une dysphagie lésionnelle d'une dysphagie non lésionnelle ?","a":"<div class=\"notion-course\"><p>Une <span class=\"nc-brown_bg\">dysphagie </span><strong><span class=\"nc-brown_bg\">lésionnelle</span></strong> est généralement évoquée par :</p><ul><li>Une prédominance sur les <strong><span class=\"nc-red nc-bold\">solides</span></strong>.</li><li>Une <strong>aggravation progressive</strong> avec le temps.</li><li>Un <strong><span class=\"nc-red nc-bold\">retentissement sur l'état général</span></strong>.</li></ul><p>Une dysphagie <strong>non lésionnelle</strong> (ou fonctionnelle/trouble moteur) est évoquée par :</p><ul><li>Une dysphagie <strong>fluctuante</strong> dans le temps.</li><li>Un <span class=\"nc-brown_bg\">retentissement </span><strong><span class=\"nc-brown_bg\">inconstant</span></strong><span class=\"nc-brown_bg\"> sur l'état général</span>.</li><li>Une <span class=\"nc-yellow_bg\">dysphagie</span> <strong><span class=\"nc-red nc-bold\">capricieuse</span></strong>, voire <span class=\"nc-red nc-bold\">paradoxale</span> (sur les <span class=\"nc-red nc-bold\">liquides</span>).</li><li>Une <span class=\"nc-yellow_bg\">endoscopie</span> <span class=\"nc-green nc-bold\">souvent </span><strong><span class=\"nc-green nc-bold\">normale</span></strong>.</li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Une <span class=\"nc-orange_bg\">dysphagie oropharyngée</span> oriente d’abord vers l’évaluation de la déglutition et des voies aériennes ; une <span class=\"nc-yellow_bg\">dysphagie</span> œsophagienne vers l’<span class=\"nc-yellow_bg\">endoscopie</span> avec biopsies, puis manométrie si indiquée. Un <span class=\"nc-orange nc-bold\">trouble moteur</span> peut constituer une maladie organique sans <span class=\"nc-blue_bg nc-bold\">obstacle</span> visible.</li></ul></div></div>"},{"i":"7f63cc78ff6b","n":273,"o":"273-5","u":"Examens complémentaires","t":"Connaître les examens complémentaires non biologiques à effectuer en deuxième intention devant une dysphagie","q":"Quels sont les points essentiels concernant les examens complémentaires non biologiques à effectuer en deuxième intention devant une dysphagie ?","a":"<div class=\"notion-course\"><p><span>Les</span> examens de seconde intention sont indiqués lorsque l'<span>EOGD</span> avec <span>biopsies</span> est <strong>normale</strong> ou techniquement insuffisante. Ils diffèrent selon que la <span>dysphagie</span> est œsophagienne ou oropharyngée.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span>Dysphagie</span> œsophagienne</h4>\n      <table>\n        <thead><tr><th>Examen</th><th>Indication et apport</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-blue_bg\">Manométrie œsophagienne</span></span></td><td>Indiquée en 2ᵉ intention si <span>dysphagie</span> inexpliquée par une <span>EOGD</span> avec <span>biopsies</span> normales ; réalisée en ambulatoire chez un patient vigile. Évalue le <span><span class=\"nc-blue_bg\">péristaltisme œsophagien</span></span> (<span><span class=\"nc-red nc-bold\">absent dans l'achalasie</span></span>) et la <span>relaxation du SIO</span> (<span>défaut de relaxation dans l'<span class=\"nc-red nc-bold\">achalasie</span></span>)</td></tr>\n          <tr><td><span>TDM thoraco-abdomino-pelvienne injectée</span></td><td>Avec opacification digestive haute : recherche une <span><span class=\"nc-red_bg\">compression extrinsèque</span></span> — <span class=\"nc-orange nc-bold\">volumineuse </span><span><span class=\"nc-orange nc-bold\">hernie hiatale par roulement</span></span>, <span><span class=\"nc-orange nc-bold\">diverticule œsophagien</span></span>, <span><span class=\"nc-orange nc-bold\">tumeur</span> médiastinale ou pulmonaire</span>, <span>adénopathies</span></td></tr>\n          <tr><td><span><span class=\"nc-blue_bg\">Écho-endoscopie haute</span></span></td><td>En cas de suspicion de <span>tumeur sous-muqueuse</span> à l'<span>EOGD</span> : caractérise la <span>lésion</span> et permet de la ponctionner</td></tr>\n          <tr><td><span>TOGD</span></td><td>Transit baryté utile en complément dans certaines situations : <span class=\"nc-red nc-bold\">achalasie</span>, <span class=\"nc-orange nc-bold\">diverticule de Zenker</span>, anomalie morphologique ou <span class=\"nc-yellow_bg\">dysphagie</span> restant inexpliquée après bilan adapté.</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span><span class=\"nc-orange_bg\">Dysphagie</span></span><span class=\"nc-orange_bg\"> oropharyngée</span></h4>\n      <table>\n        <thead><tr><th>Examen</th><th>Apport</th></tr></thead>\n        <tbody>\n          <tr><td>Exploration de la prise alimentaire</td><td>Repas test pris devant un <span>observateur</span> médical ou paramédical (<span class=\"nc-brown_bg\">diététicienne</span>, <span class=\"nc-brown_bg\">orthophoniste</span>, IDE, aide-soignant) ; au terme du repas, des <span>adaptations de texture</span> peuvent être décidées</td></tr>\n          <tr><td><span><span class=\"nc-yellow_bg\">Nasofibroscopie</span> de la déglutition</span></td><td>Peu invasive ; observe le carrefour pharyngo-laryngé lors de la déglutition d'aliments de consistance variable ; diagnostic indirect des troubles (<span>toux</span>, <span class=\"nc-yellow_bg\">stase salivaire</span>, résidus hypopharyngés, <span class=\"nc-blue_bg\">fausses routes</span> secondaires)</td></tr>\n          <tr><td><span>Radio-cinéma de déglutition</span> (<span class=\"nc-blue nc-bold\">vidéo-fluoroscopie</span>)</td><td>Vidéofluoroscopie : examen dynamique des temps oral, pharyngé et œsophagien ; permet d’étudier les <span class=\"nc-blue_bg\">fausses routes</span> et les adaptations de posture ou de consistance. Position adaptée au patient et au protocole, généralement assise ; irradiation et coopération à prendre en compte.</td></tr>\n          <tr><td><span>Panendoscopie ORL</span></td><td>Tube rigide sous <span>anesthésie générale</span> ; examine le <span class=\"nc-pink nc-bold\">pharynx</span> et la <span class=\"nc-pink nc-bold\">bouche œsophagienne</span> — indispensable au bilan d'un <span>carcinome des VADS</span></td></tr>\n          <tr><td><span>TDM cervico-thoracique</span></td><td><strong>Systématique en cas de <span class=\"nc-red nc-bold\">paralysie laryngée</span></strong> : recherche une <span>compression du <span class=\"nc-purple_bg\">nerf vague (X)</span></span> ; recherche aussi une <span class=\"nc-red_bg\">compression extrinsèque</span></td></tr>\n          <tr><td><span>IRM du tronc cérébral</span></td><td>IRM du tronc cérébral si suspicion <span class=\"nc-orange nc-bold\">neurologique</span> centrale ; ce n’est pas un examen systématique de toute <span class=\"nc-blue_bg\">dysphagie</span> inexpliquée.</td></tr>\n        </tbody>\n      </table></div>"},{"i":"751ad05bf322","n":273,"o":"273-7","u":"Diagnostic positif","t":"Connaître les principales étiologies d’une dysphagie d’origine pharyngolaryngée et en apprécier la gravité","q":"Quels sont les points essentiels concernant les principales étiologies d’une dysphagie d’origine pharyngolaryngée et en apprécier la gravité ?","a":"<div class=\"notion-course\"><p>La <span><span class=\"nc-blue_bg\">dysphagie</span></span> d'origine pharyngo-laryngée (oropharyngée) relève de causes <span class=\"nc-orange nc-bold\">ORL</span> et neurologiques. L'appréciation de sa gravité est essentielle : elle expose à des complications respiratoires et nutritionnelles.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Étiologies</h4>\n      <table>\n        <thead><tr><th>Catégorie</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td>Causes tumorales</td><td><span>Cancer du <span class=\"nc-red nc-bold\">pharynx</span></span>, du <span><span class=\"nc-red nc-bold\">larynx</span></span>, du <span><span class=\"nc-red nc-bold\">1/3 supérieur de l'œsophage</span></span> ; <span>cancer de la cavité buccale</span> (<span><span class=\"nc-blue_bg\">dysphagie</span></span> alors tardive)</td></tr>\n          <tr><td>Causes extrinsèques</td><td><span><span class=\"nc-blue_bg\">Volumineux goitre thyroïdien plongeant</span></span> ; <span><span class=\"nc-blue_bg\">anévrisme de l'aorte thoracique</span></span> ; <span><span class=\"nc-red nc-bold\">tumeurs du médiastin</span></span> ; <span><span class=\"nc-blue_bg\">anomalie vertébrale</span></span> — la <span>TDM</span> thoracique injectée précise l'extension</td></tr>\n          <tr><td>Atteinte du SSO</td><td><span><span class=\"nc-orange_bg\">Diverticule de Zenker</span></span> ; <span>achalasie du sphincter supérieur</span> (hypertonie du crico-pharyngien) ; <span><span class=\"nc-orange nc-bold\">syndrome de Plummer-Vinson</span></span> ; <span>séquelles d'ingestion de <span class=\"nc-orange nc-bold\">caustique</span></span></td></tr>\n          <tr><td>Causes neurologiques</td><td>Maladies neurodégénératives (<span><span class=\"nc-red_bg\">Parkinson</span></span>, <span><span class=\"nc-red_bg\">Alzheimer</span></span>, <span class=\"nc-red_bg\">démence sénile</span>) ; <span><span class=\"nc-orange_bg\">myasthénie</span></span> ; <span><span class=\"nc-orange_bg\">AVC</span></span> ; <span><span class=\"nc-orange_bg\">SLA</span></span> ; <span><span class=\"nc-orange_bg\">paralysie unilatérale du nerf vague</span></span> ; <span><span class=\"nc-orange_bg\">myopathie</span></span> ; <span><span class=\"nc-red_bg\">syndrome pseudobulbaire</span></span><span class=\"nc-red_bg\"> d'origine vasculaire</span></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Appréciation de la gravité</h4>\n      <div class=\"callout callout-danger\"><strong><span>Signes de gravité</span> 🚩</strong> — <span><span class=\"nc-yellow_bg\">fausses routes</span></span><span class=\"nc-yellow_bg\"> alimentaires ou salivaires</span> ; <span>pneumopathies d'inhalation à répétition</span> ; <span><span class=\"nc-red_bg\">dénutrition</span></span> ; <span><span class=\"nc-red_bg\">déshydratation</span></span> ; <span><span class=\"nc-brown_bg\">otalgie réflexe</span></span> (<span>drapeau rouge</span> devant faire rechercher un cancer).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 298 — Tumeur cavité buccale-nasosinusienne-cavum-VADS · 98 — <span class=\"nc-orange_bg\">Myasthénie</span> · 106 — <span class=\"nc-red_bg\">Parkinson</span></em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Le transit baryté reste utile dans certaines indications, notamment diverticule de Zenker ou <span class=\"nc-red nc-bold\">achalasie</span>. La vidéofluoroscopie étudie la déglutition dans des conditions adaptées ; elle n’impose pas systématiquement le décubitus. L’IRM n’est pas un examen de routine de toute <span class=\"nc-yellow_bg\">dysphagie</span> inexpliquée.</li></ul></div></div>"},{"i":"d5d4f2fc2702","n":273,"o":"273-8","u":"Contenu multimédia","t":"Radiographie typique d’un corps étranger pharyngo-œsophagien","q":"Quels sont les points essentiels concernant radiographie typique d’un corps étranger pharyngo-œsophagien ?","a":"<div class=\"notion-course\"><p>Devant la suspicion d'un <span>corps <span class=\"nc-red nc-bold\">étranger</span> pharyngo-œsophagien</span>, l'examen de débrouillage est une <span>radiographie simple sans opacification</span>, réalisée de <strong>face et de profil</strong>. Le corps <span class=\"nc-red nc-bold\">étranger</span> se situe en règle générale dans l'œsophage cervical, en regard du <span>sphincter supérieur de l'œsophage (SSO)</span>.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Aspect radiographique typique</h4>\n      <ul>\n        <li><strong>Corps <span class=\"nc-red nc-bold\">étranger</span> radio-opaque :</strong> situé <span class=\"nc-red nc-bold\">au niveau cervical</span> ou déjà en aval ; de profil, il se projette <span>en arrière de la trachée, en position prérachidienne</span>.</li>\n        <li><strong>Pile bouton</strong> (corps <span class=\"nc-red nc-bold\">étranger</span> dangereux) : aspect caractéristique en <span>doubles contours</span> sur la <span>radiographie</span>.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Signes radiographiques de complication</h4>\n      <p>Une <span class=\"nc-red_bg\">perforation avec médiastinite</span> se traduit par :</p>\n      <ul>\n        <li><span>Épanchement gazeux</span></li>\n        <li><span>Épaississement des parties molles cervico-médiastinales</span></li>\n        <li><span>Signe de Minigerode</span> : image claire pré-vertébrale sur la <span>radiographie</span> de profil</li>\n        <li><span>Emphysème médiastinal</span> sous forme d'une ligne bordante de la silhouette cardiaque</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Pile bouton — <span>urgence</span> 🚩</strong> — risque de <span><span class=\"nc-red nc-bold\">corrosion chimique</span></span> conduisant à une <span><span class=\"nc-red nc-bold\">perforation par nécrose</span></span> (<span class=\"nc-red_bg\">médiastinite</span>, <span>hémorragie massive</span> par <span>lésion</span> vasculaire). L'aspect en doubles contours et l'interrogatoire orientent le diagnostic ; extraction en urgence.</div>\n      </div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/1cb37f85d9418164839cdbb1893c15c4?pvs=204","reviewedAt":"2026-10-16","batch":"digestive-infectious-50","verification":"reviewed","note":"Relecture et contrôles du lot réalisés. LiSA : copies locales ; ordinateur et format iPad simulé."}};
